import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DGu13UIe.js";const s="/bagent/showcase/ama.png",n="/bagent/showcase/foodmap.png",c="/bagent/showcase/swiss.png",f=JSON.parse('{"title":"案例","description":"","frontmatter":{},"headers":[],"relativePath":"guide/showcase.md","filePath":"guide/showcase.md"}'),p={name:"guide/showcase.md"};function h(i,e,g,d,l,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="案例" tabindex="-1">案例 <a class="header-anchor" href="#案例" aria-label="Permalink to &quot;案例&quot;">​</a></h1><p><strong>bagent</strong> 做完之后，是侧边栏里一个能动手干活的 <strong>code agent</strong>。背包的比喻很简单：东西不多，拉链拉开就能看清；背在编辑器里跟着项目走，不是把你拽进一套沉重 framework。危险操作会弹窗让你确认。</p><p>下面是三个真实截图，都是同一套插件对话出来的。</p><hr><h2 id="案例一-联网查资料-生成-html-页面" tabindex="-1">案例一：联网查资料，生成 HTML 页面 <a class="header-anchor" href="#案例一-联网查资料-生成-html-页面" aria-label="Permalink to &quot;案例一：联网查资料，生成 HTML 页面&quot;">​</a></h2><p><img src="'+s+'" alt="电影投资小报"></p><p><strong>用户说什么：</strong> 做一份关于电影 <a href="https://movie.douban.com/subject/37116446/" target="_blank" rel="noreferrer">《给阿嬷的情书》</a> 的投资回报小报，要能在浏览器里打开看。</p><p><strong>Agent 做了什么：</strong> 先上网查票房、成本、出品方等信息，再写一个 <code>amam-report.html</code>，左侧预览就是成稿。后面用户还提了「版式再大胆一点」，Agent 继续改样式。</p><hr><h2 id="案例二-在已有页面上改-ui" tabindex="-1">案例二：在已有页面上改 UI <a class="header-anchor" href="#案例二-在已有页面上改-ui" aria-label="Permalink to &quot;案例二：在已有页面上改 UI&quot;">​</a></h2><p><img src="'+n+'" alt="京都美食地图"></p><p><strong>用户说什么：</strong> 这个美食地图页面已经有了；把悬浮卡片的圆角收小一点，再加些广告位和分享按钮，看起来更真。</p><p><strong>Agent 做了什么：</strong> 直接改 <code>food-map.html</code> 里的 CSS 和结构，不用整页重写。截图里能看到两次小改，改完刷新预览即可。</p><hr><h2 id="案例三-用-c-写数据结构并测试" tabindex="-1">案例三：用 C 写数据结构并测试 <a class="header-anchor" href="#案例三-用-c-写数据结构并测试" aria-label="Permalink to &quot;案例三：用 C 写数据结构并测试&quot;">​</a></h2><p><img src="'+c+'" alt="Swiss Table"></p><p><strong>用户说什么：</strong> 用 C 实现一个简单的 Swiss Table（开放寻址哈希表），并写测试。</p><p><strong>Agent 做了什么：</strong> 先列计划（头文件 → 实现 → 测试），再逐个写出 <code>.h</code> / <code>.c</code> 文件。终端里的编译和测试结果是用户在本地跑的；Agent 负责把代码写出来。</p><hr><p>想自己动手做同款 agent，从 <a href="/bagent/chapters/00-preface.html">第 0 章 前言</a> 或 <a href="/bagent/chapters/01-deepseek.html">第 1 课</a> 开始跟即可。</p>',20)])])}const u=a(p,[["render",h]]);export{f as __pageData,u as default};
